<div class="relatorio-header"><h1 class="relatorio-titulo">Mapear colunas</h1></div><div class="form-card"><form method="post" action="<?=URL_BASE?>/importacao/processar"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token)?>"><?php foreach(['data_transacao'=>'Data','valor'=>'Valor','tipo'=>'Tipo','filial_id'=>'Filial (ID)','categoria_id'=>'Categoria (ID)','descricao'=>'Descrição','metodo_pagamento'=>'Método'] as $campo=>$rotulo):?><label><?=$rotulo?></label><select name="mapa[<?=$campo?>]"><option value="">Não importar</option><?php foreach($cabecalhos as $i=>$h):?><option value="<?=$i?>"><?=htmlspecialchars($h?:'Coluna '.($i+1))?></option><?php endforeach?></select><?php endforeach?><button class="btn btn-primary">Validar e importar</button></form></div>
